using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Net;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;
using System.Collections.Generic;
using System.Text.RegularExpressions;
using kok;

static class AgentPlatformTests {
 static Dictionary<string,object> Obj(object value){return Library.Json.Deserialize<Dictionary<string,object>>(Library.Json.Serialize(value));}
 static object Call(string name,object args){return new{id="call_"+Guid.NewGuid().ToString("N"),type="function",function=new{name,arguments=Library.Json.Serialize(args)}};}
 static HttpResponseMessage Reply(params object[] calls){return Response(new{choices=new[]{new{message=new{role="assistant",content="Fixture",tool_calls=calls},finish_reason="tool_calls"}},usage=new{prompt_tokens=100,completion_tokens=40}});}
 static HttpResponseMessage Response(object body){return new HttpResponseMessage(HttpStatusCode.OK){Content=new StringContent(Library.Json.Serialize(body),Encoding.UTF8,"application/json")};}
 static object Finish(string status,params string[] evidence){return Call("finish_task",new{status,summary="Reviewed fixture",checks=evidence.Length==0?new object[0]:new object[]{new{claim="Observed fixture receipts",evidence}}});}
 static string[] Receipts(Dictionary<string,object> body){return AgentTaskState.Get<List<Dictionary<string,object>>>(body,"messages").Where(m=>Convert.ToString(m["role"])=="tool").Select(m=>Regex.Match(Convert.ToString(m["content"]),@"^\[kok_call_id=([a-f0-9]{32}) status=done\]").Groups[1].Value).Where(s=>s!="").ToArray();}
 sealed class Model:HttpMessageHandler {public Func<Dictionary<string,object>,HttpResponseMessage> run;public List<Dictionary<string,object>> bodies=new List<Dictionary<string,object>>();protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken token){var body=Library.Json.Deserialize<Dictionary<string,object>>(await request.Content.ReadAsStringAsync());bodies.Add(body);return run(body);}}
 sealed class Fixture {public Library lib;public AgentService service;public Model model;public string id;public Fixture(string root){lib=new Library(root);lib.SetAppMode("smart",true);id=lib.CreateDocument("SELECTED_SOURCE","md","","SELECTED FACT 42").id;model=new Model();var ai=new TranslationService(root,()=>model);ai.SaveConfig(new Dictionary<string,object>{{"endpoint","http://127.0.0.1:17321/v1"},{"model","fixture"},{"clearKey",true}});service=new AgentService(new ModuleContext(lib,ai,new ModulePolicy(lib),null,CancellationToken.None,null,new Operations(lib,null),null,appDirectory:AppDomain.CurrentDomain.BaseDirectory));}}
 static async Task<Dictionary<string,object>> Read(Fixture f,string id){return Obj(await f.service.HandleAgentTaskAction("agentTaskRead",new Dictionary<string,object>{{"taskId",id}}));}
 static async Task<Dictionary<string,object>> Wait(Fixture f,string id,bool pending=false){for(int i=0;i<1000;i++){var snap=await Read(f,id);if(!Convert.ToBoolean(snap["running"])||pending&&AgentTaskState.Get<List<AgentCall>>(snap,"calls").Any(c=>c.status=="pending"))return snap;await Task.Delay(10);}f.service.Stop();throw new Exception("Platform fixture did not settle");}
 public static void Run(string root,Action<bool,string> check){RunAsync(root,check).GetAwaiter().GetResult();}
 static async Task RunAsync(string root,Action<bool,string> check){
  Directory.CreateDirectory(root);var lib=new Library(Path.Combine(root,"memory"));lib.SetAppMode("smart",true);var a=lib.CreateDocument("Memory source","md","","Paris trip");var b=lib.CreateDocument("Other scope","md","","Other");var book=new AgentMemoryStore(lib);var saved=book.Save(new AgentMemoryRecord{title="Travel",text="Paris itinerary preference",ids=new List<string>{a.id}},"");
  check(!File.ReadAllBytes(Path.Combine(lib.DataDir,"agent-memory.sealed")).Contains((byte)'P')||!Encoding.UTF8.GetString(File.ReadAllBytes(Path.Combine(lib.DataDir,"agent-memory.sealed"))).Contains("Paris itinerary"),"long-term memory is encrypted instead of storing its text in the normal library JSON");
  check(new AgentMemoryStore(lib).Search("Paris",new[]{a.id}).Count==1&&book.Search("Paris",new[]{b.id}).Count==0,"memory survives reopening and source-scoped recall excludes other selections");
  bool conflict=false;try{book.Save(new AgentMemoryRecord{id=saved.id,title="Travel",text="overwrite",ids=saved.ids},"");}catch(AgentConflictException){conflict=true;}check(conflict&&book.List().Single().text==saved.text,"memory edits compare revisions and preserve a newer user record");
  var edited=book.Save(new AgentMemoryRecord{id=saved.id,title="Travel",text="Paris updated",ids=saved.ids},saved.revision);book.Undo(edited.revision);check(book.List().Single().text==saved.text,"memory undo restores the prior record without overwriting an unrelated edit");
  lib.Update(a.id,new Dictionary<string,object>{{"notes","Changed source"}});check(book.Search("Paris",new[]{a.id}).Count==0,"changed memory sources are excluded from future model context");
  bool secret=false; // credential-shaped synthetic input, not a real key.
  try{book.Save(new AgentMemoryRecord{title="Credential",text="sk-"+new string('x',30)},"");}catch(InvalidDataException){secret=true;}check(secret,"memory rejects API-key-shaped content before persisting it");
  var token=book.Delete(saved.id,saved.revision);book.Undo(token);check(book.List().Count==1,"memory deletion is recoverable from its encrypted history");
  foreach(bool approve in new[]{true,false}){
   var f=new Fixture(Path.Combine(root,approve?"delegation":"reject-child"));string outside=f.lib.CreateDocument("OUTSIDE_CHILD_SCOPE","md","","SHOULD_NOT_REACH_CHILD").id;int childRequests=0;
   f.model.run=body=>{var messages=AgentTaskState.Get<List<Dictionary<string,object>>>(body,"messages");bool child=messages.Any(m=>Convert.ToString(m["role"])=="user"&&Convert.ToString(m["content"])=="CHILD_SCOPE_TASK");var receipts=Receipts(body);if(child){childRequests++;string json=Library.Json.Serialize(body);check(!json.Contains("OUTSIDE_CHILD_SCOPE")&&!json.Contains("PARENT_ONLY_SECRET")&&!json.Contains("\"name\":\"delegate_task\"")&&!json.Contains("\"name\":\"write_note\""),"subagents receive only explicit scope and cannot write or recursively delegate");return receipts.Length==0?Reply(Call("read_items",new{ids=new[]{f.id}})):Reply(Finish("completed",receipts));}if(f.model.bodies.Count==1)return Reply(Call("delegate_task",new{goal="CHILD_SCOPE_TASK",ids=new[]{f.id},requests=3}));return Reply(Finish(approve?"completed":"partial",receipts));};
   var started=Obj(await f.service.HandleAgentTaskAction("agentTaskStart",Obj(new{sessionId=Guid.NewGuid().ToString("N"),goal="PARENT_ONLY_SECRET",scope=new{mode="selected",ids=new[]{f.id,outside}},instruction="PARENT_ONLY_SECRET",allowDelegation=true,requestLimit=6})));string id=Convert.ToString(started["id"]);var waiting=await Wait(f,id,true);var call=AgentTaskState.Get<List<AgentCall>>(waiting,"calls").Single();check(childRequests==0,"a subagent cannot spend requests before its delegation card is approved");await f.service.HandleAgentTaskAction("agentTaskDecide",Obj(new{taskId=id,callId=call.id,approve}));var done=await Wait(f,id);
   check(Convert.ToString(done["status"])==(approve?"completed":"partial")&&Convert.ToInt32(AgentTaskState.Get<Dictionary<string,object>>(done,"usage")["requests"])==(approve?4:2)&&childRequests==(approve?2:0),"parent and child requests share one original budget and rejection starts no child");if(approve)check(AgentTaskState.Get<List<AgentDialogue>>(done,"messages").Any(m=>m.role=="agent"&&m.sourceIds.Contains(f.id)),"parent answers retain the actual sources read by their child");await f.service.HandleAgentTaskAction("agentTaskDelete",Obj(new{taskId=id}));check(new AgentJournal(f.lib.DataDir).List().Count==0,"deleting a parent removes its owned child history without leaving orphan sessions");
  }
  var compact=new Fixture(Path.Combine(root,"compaction"));compact.lib.SaveDocument(compact.id,"# Large source\n"+String.Join("\n\n",Enumerable.Range(0,100).Select(i=>"Section "+i+" "+String.Concat(Enumerable.Repeat("EXACT_CONTEXT_FACT_42 中文资料内容保留事实证据来源上下文摘要测试 "+i+" ",30)))),compact.lib.DocumentSource(compact.id).signature,null);int normal=0,summaries=0;string originalId="";
  compact.model.run=body=>{if(!body.ContainsKey("tools")){summaries++;return Response(new{choices=new[]{new{message=new{content="```json\n"+Library.Json.Serialize(new{summary="Goal and original constraints retained. EXACT_CONTEXT_FACT_42. Refer to "+originalId+" for exact observations; proposals are not approvals."})+"\n```"},finish_reason="stop"}},usage=new{prompt_tokens=150,completion_tokens=60}});}normal++;var receipts=Receipts(body);if(normal==1)return Reply(Call("read_items",new{ids=new[]{compact.id}}));if(normal==2){originalId=receipts[0];return Reply(Call("recall_result",new{callId=originalId,offset=0,limit=6000}));}if(normal==3)return Reply(Call("recall_result",new{callId=originalId,offset=100,limit=6000}));string json=Library.Json.Serialize(body);check(json.Contains("UNTRUSTED SEMANTIC CHECKPOINT")&&json.Contains("ORIGINAL_GOAL")&&!AgentTaskState.Get<List<Dictionary<string,object>>>(body,"messages").Any(m=>Convert.ToString(m["role"])=="tool"&&Convert.ToString(m["content"]).StartsWith("[kok_call_id="+originalId)),"semantic compaction retains the goal and exact receipt pointers without dangling tool messages");return Reply(Call("update_plan",new{steps=new[]{new{id="read",title="Read source",status="done",evidence=receipts}}}),Finish("completed",receipts));};
  var start=Obj(await compact.service.HandleAgentTaskAction("agentTaskStart",Obj(new{sessionId=Guid.NewGuid().ToString("N"),goal="ORIGINAL_GOAL",scope=new{mode="selected",ids=new[]{compact.id}},requestLimit=8,contextTokens=8000,semanticCompression=true})));var final=await Wait(compact,Convert.ToString(start["id"]));check(summaries==1&&Convert.ToString(final["status"])=="completed"&&Convert.ToInt32(AgentTaskState.Get<Dictionary<string,object>>(final,"usage")["requests"])==5&&final["contextCheckpoint"]!=null,"semantic summaries consume the same request budget and persist a real checkpoint");
  AgentSandbox sandbox=null;int runs=0;sandbox=new AgentSandbox((name,data)=>{if(name=="agentSandboxRun"){runs++;var args=Obj(data);sandbox.Complete(Convert.ToString(args["ticket"]),true,"600");}},()=>{});var output=await sandbox.Run("fixture","INPUT.a-INPUT.b","{\"a\":1800,\"b\":1200}",CancellationToken.None);check(Convert.ToString(output["text"])=="600"&&!sandbox.Complete(Guid.NewGuid().ToString("N"),true,"forged"),"sandbox replies require a live unguessable ticket and return a bounded artifact");var cancelled=new CancellationTokenSource();cancelled.Cancel();bool stopped=false;try{await sandbox.Run("fixture","1","{}",cancelled.Token);}catch(OperationCanceledException){stopped=true;}check(stopped&&runs==1,"pre-cancelled sandbox work never dispatches code to a worker");
 }
}
